mapper.select:
SELECT
m_no, m_email, m_password, m_name, m_social, m_class, m_created, m_address
FROM member

    
        
            
                AND m_name  LIKE CONCAT('%', #{keyword}, '%')
            
            
                AND m_email LIKE CONCAT('%', #{keyword}, '%')
            
        
    
    
        AND m_class = #{cls}
    
    
        AND m_social = #{social}
    
    
        AND m_created >= CONCAT(#{from}, ' 00:00:00')
    
    
        AND m_created <= CONCAT(#{to}, ' 23:59:59')
    

ORDER BY m_no DESC

    LIMIT #{limit}
    
        OFFSET #{offset}

mapper.update:
UPDATE member
SET m_password = #{hashed}
WHERE m_no = #{m_no}

mapper.insert:
INSERT INTO member (
m_email, m_password, m_name, m_social, m_class, m_address, m_created
) VALUES (
#{m_email}, #{m_password}, #{m_name}, #{m_social}, #{m_class}, #{m_address}, NOW()
)
